#!/usr/bin/env python3
"""Digital assembly plan of the Italia 128 model by sectors, from compose.py outputs + measured densities of the V0.5.3 diorama (results/diorama_v053).
Writes output/sector_plan.json and output/sector_overlay.png. Estimates are engineering estimates, not a bill of materials."""
import json, os, sys
import numpy as np
from PIL import Image, ImageDraw
HERE = os.path.dirname(os.path.abspath(__file__)); out = os.path.join(HERE, "output"); cfg = json.load(open(os.path.join(HERE, "artistic_scale_config.json")))
lev = np.load(os.path.join(out, "levels_128.npy")); pl = json.load(open(os.path.join(out, "placements.json"))); dens = json.load(open(os.path.join(out, "densities.json")))
SR, SC = cfg["sectors"]["size_studs"]; GR, GC = lev.shape; sectors = []
for i in range(GR // SR):
    for j in range(GC // SC):
        blk = lev[i * SR:(i + 1) * SR, j * SC:(j + 1) * SC]; land = int((blk > 0).sum()); mons = [m["id"] for m in pl["monuments"] if m["row"] < (i + 1) * SR and m["row"] + m["footprint"][0] > i * SR and m["col"] < (j + 1) * SC and m["col"] + m["footprint"][1] > j * SC]
        zones = [z for z, v in pl["zones"].items() if v["row"] < (i + 1) * SR and v["row"] + v["h"] > i * SR and v["col"] < (j + 1) * SC and v["col"] + v["w"] > j * SC]
        sea = SR * SC - land; relief = float(blk[blk > 0].mean()) if land else 0.0
        est = sea * dens["base_pieces_per_cell"] + land * (dens["land_pieces_per_cell_flat"] + dens["land_pieces_per_cell_per_level"] * relief) + sum(dens["monument_pieces"].get(m, 0) for m in mons) + (dens["lettering_pieces"] if "title" in zones else 0) + (dens["compass_pieces"] if "compass" in zones else 0)
        sectors.append(dict(id="S%d%d" % (i, j), row0=i * SR, col0=j * SC, land_cells=land, mean_level=round(relief, 2), max_level=int(blk.max()), monuments=mons, zones=zones, est_pieces=int(est), kind="open sea" if land == 0 and not zones else "mixed"))
frame = 2 * (GR + GC + 4) * 2 * dens["frame_pieces_per_stud"]; tot = sum(s["est_pieces"] for s in sectors) + frame
plan = dict(sectors=sectors, frame_est_pieces=int(frame), total_est_pieces=int(tot), total_est_range=[int(tot * 0.75), int(tot * 1.35)], densities=dens, build_order=["1 base: 8x8 dark-grey plates (16x16 grid) then staggered second layer straddling sector seams", "2 sea plates level 2 (all sectors)", "3 for each sector in reading order: terrain layers k=0..K (bricks, slopes), then beaches, forest pads/conifers, relief plates", "4 monument sub-models (own LDraw sub-file, placed as a unit on its plaza)", "5 title + compass tiles", "6 frame ring (2 studs)", "7 final seam check: engine-1 validation of the merged model + per-sector validation with 4-stud halo"], notes=["Sector halo cells are generated by both neighbours from the same global heightfield : identical, so a single owner (lower index) emits the pieces", "Sectors are cut on the 8-stud base-plate grid so no piece crosses a sector boundary except the seam backing layer"])
json.dump(plan, open(os.path.join(out, "sector_plan.json"), "w"), indent=1)
im = Image.open(os.path.join(out, "composition_preview.png")).convert("RGB"); d = ImageDraw.Draw(im); F = cfg["geographic"]["frame_studs"]; PX = 8
for s in sectors:
    x, y = (s["col0"] + F) * PX, (s["row0"] + F) * PX; d.rectangle([x, y, x + SC * PX, y + SR * PX], outline=(255, 255, 0), width=1); d.text((x + 4, y + 3), "%s ~%d" % (s["id"], s["est_pieces"]), fill=(255, 255, 0))
im.save(os.path.join(out, "sector_overlay.png")); print(json.dumps({k: plan[k] for k in ("total_est_pieces", "total_est_range", "frame_est_pieces")}))
